3e\\u0440\\u0438\\u0442\\u043c \\u043f\\u0440\\u0438\\u043d\\u0438\\u043c\\u0430\\u0435\\u0442 \\u0440\\u0435\\u0448\\u0435\\u043d\\u0438\\u044f \\u043d\\u0430 \\u0441\\u0430\\u043c\\u043e\\u043c \\u0434\\u0435\\u043b\\u0435."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "\\u041f\\u043e\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043a\\u0430 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0438"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "\\u0414\\u0430\\u043d \\u043d\\u0435\\u0431\\u043e\\u043b\\u044c\\u0448\\u043e\\u0439 \\u043d\\u0430\\u0431\\u043e\\u0440 \\u0434\\u0430\\u043d\\u043d\\u044b\\u0445: \\u043f\\u0440\\u0438\\u0437\\u043d\\u0430\\u043a x \\u0438 \\u0446\\u0435\\u043b\\u0435\\u0432\\u0430\\u044f \\u043f\\u0435\\u0440\\u0435\\u043c\\u0435\\u043d\\u043d\\u0430\\u044f y. \\u0422\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442\\u0441\\u044f \\u043d\\u0430\\u0439\\u0442\\u0438 \\u043b\\u0443\\u0447\\u0448\\u0438\\u0439 \\u043f\\u0435\\u0440\\u0432\\u044b\\u0439 \\u043f\\u043e\\u0440\\u043e\\u0433 \\u0434\\u043b\\u044f \\u0440\\u0430\\u0437\\u0431\\u0438\\u0435\\u043d\\u0438\\u044f \\u043f\\u043e \\u043a\\u0440\\u0438\\u0442\\u0435\\u0440\\u0438\\u044e \\u043c\\u0438\\u043d\\u0438\\u043c\\u0438\\u0437\\u0430\\u0446\\u0438\\u0438 MSE, \\u0432\\u044b\\u0447\\u0438\\u0441\\u043b\\u0438\\u0442\\u044c \\u0438\\u043d\\u0444\\u043e\\u0440\\u043c\\u0430\\u0446\\u0438\\u043e\\u043d\\u043d\\u044b\\u0439 \\u043f\\u0440\\u0438\\u0440\\u043e\\u0441\\u0442 \\u0438 \\u0441\\u0440\\u0430\\u0432\\u043d\\u0438\\u0442\\u044c \\u0441 \\u0430\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u044b\\u043c\\u0438 \\u043f\\u043e\\u0440\\u043e\\u0433\\u0430\\u043c\\u0438."}]}, {"type": "codeBlock", "attrs": {"language": "python"}, "content": [{"type": "text", "text": "x = [1, 2, 3, 4, 5, 6, 7, 8]\\ny = [2, 4, 5, 4, 5, 7, 8, 9]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "\\u0428\\u0430\\u0433 1: \\u0412\\u044b\\u0447\\u0438\\u0441\\u043b\\u0435\\u043d\\u0438\\u0435 MSE \\u0434\\u043b\\u044f \\u043a\\u043e\\u0440\\u043d\\u0435\\u0432\\u043e\\u0433\\u043e \\u0443\\u0437\\u043b\\u0430"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "\\u0421\\u043d\\u0430\\u0447\\u0430\\u043b\\u0430 \\u043d\\u0430\\u0439\\u0434\\u0451\\u043c MSE \\u0434\\u043b\\u044f \\u0432\\u0441\\u0435\\u0433\\u043e \\u043d\\u0430\\u0431\\u043e\\u0440\\u0430 \\u0434\\u0430\\u043d\\u043d\\u044b\\u0445 (\\u0431\\u0435\\u0437 \\u0440\\u0430\\u0437\\u0431\\u0438\\u0435\\u043d\\u0438\\u044f). \\u042d\\u0442\\u043e \\u0431\\u0443\\u0434\\u0435\\u0442 \\u043e\\u0442\\u043f\\u0440\\u0430\\u0432\\u043d\\u043e\\u0439 \\u0442\\u043e\\u0447\\u043a\\u043e\\u0439 \\u0434\\u043b\\u044f \\u043e\\u0446\\u0435\\u043d\\u043a\\u0438 \\u0443\\u043b\\u0443\\u0447\\u0448\\u0435\\u043d\\u0438\\u044f."}]}, {"type": "codeBlock", "attrs": {"language": "python"}, "content": [{"type": "text", "text": "import numpy as np\\n\\ndef mse(y):\\n    return np.mean((y - np.mean(y))**2)\\n\\nmse_root = mse(y)\\nprint(f\\"MSE \\u043a\\u043e\\u0440\\u043d\\u0435\\u0432\\u043e\\u0433\\u043e \\u0443\\u0437\\u043b\\u0430: {mse_root:.3f}\\")"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "\\u0412\\u044b\\u0447\\u0438\\u0441\\u043b\\u0438\\u043c \\u0432\\u0440\\u0443\\u0447\\u043d\\u0443\\u044e: \\u0441\\u0440\\u0435\\u0434\\u043d\\u0435\\u0435 y = (2+4+5+4+5+7+8+9)/8 = 44/8 = 5.5. \\u041e\\u0442\\u043a\\u043b\\u043e\\u043d\\u0435\\u043d\\u0438\\u044f: (-3.5, -1.5, -0.5, -1.5, -0.5, 1.5, 2.5, 3.5). \\u041a\\u0432\\u0430\\u0434\\u0440\\u0430\\u0442\\u044b: (12.25, 2.25, 0.25, 2.25, 0.25, 2.25, 6.25, 12.25). \\u0421\\u0443\\u043c\\u043c\\u0430 = 38.0. MSE = 38/8 = 4.75."}]}, {"type": "calloutInfo", "content": [{"type": "text", "text": "MSE \\u043a\\u043e\\u0440\\u043d\\u0435\\u0432\\u043e\\u0433\\u043e \\u0443\\u0437\\u043b\\u0430 = 4.75. \\u042d\\u0442\\u043e \\u0437\\u043d\\u0430\\u0447\\u0435\\u043d\\u0438\\u0435 \\u043c\\u044b \\u0431\\u0443\\u0434\\u0435\\u043c \\u043f\\u044b\\u0442\\u0430\\u0442\\u044c\\u0441\\u044f \\u0443\\u043c\\u0435\\u043d\\u044c\\u0448\\u0438\\u0442\\u044c \\u0441 \\u043f\\u043e\\u043c\\u043e\\u0449\\u044c\\u044e \\u0440\\u0430\\u0437\\u0431\\u0438\\u0435\\u043d\\u0438\\u044f."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "\\u0428\\u0430\\u0433 2: \\u041f\\u0435\\u0440\\u0435\\u0431\\u043e\\u0440 \\u043f\\u043e\\u0440\\u043e\\u0433\\u043e\\u0432 \\u0438 \\u0432\\u044b\\u0447\\u0438\\u0441\\u043b\\u0435\\u043d\\u0438\\u0435 \\u0438\\u043d\\u0444\\u043e\\u0440\\u043c\\u0430\\u0446\\u0438\\u043e\\u043d\\u043d\\u043e\\u0433\\u043e \\u043f\\u0440\\u0438\\u0440\\u043e\\u0441\\u0442\\u0430"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "\\u0414\\u043b\\u044f \\u043a\\u0430\\u0436\\u0434\\u043e\\u0433\\u043e \\u0432\\u043e\\u0437\\u043c\\u043e\\u0436\\u043d\\u043e\\u0433\\u043e \\u043f\\u043e\\u0440\\u043e\\u0433\\u0430 t (\\u043c\\u0435\\u0436\\u0434\\u0443 \\u0441\\u043e\\u0441\\u0435\\u0434\\u043d\\u0438\\u043c\\u0438 \\u0437\\u043d\\u0430\\u0447\\u0435\\u043d\\u0438\\u044f\\u043c\\u0438 x) \\u0440\\u0430\\u0437\\u043e\\u0431\\u044c\\u0451\\u043c \\u0434\\u0430\\u043d\\u043d\\u044b\\u0435 \\u043d\\u0430 \\u043b\\u0435\\u0432\\u0443\\u044e \\u0438 \\u043f\\u0440\\u0430\\u0432\\u0443\\u044e \\u0447\\u0430\\u0441\\u0442\\u0438: x <= t \\u0438 x > t. \\u0412\\u044b\\u0447\\u0438\\u0441\\u043b\\u0438\\u043c MSE \\u0434\\u043b\\u044f \\u043a\\u0430\\u0436\\u0434\\u043e\\u0439 \\u0447\\u0430\\u0441\\u0442\\u0438 \\u0438 \\u0432\\u0437\\u0432\\u0435\\u0448\\u0435\\u043d\\u043d\\u0443\\u044e \\u0441\\u0443\\u043c\\u043c\\u0443."}]}, {"type": "codeBlock", "attrs": {"language": "python"}, "content": [{"type": "text", "text": "def weighted_mse(left_y, right_y):\\n    n_left = len(left_y)\\n    n_right = len(right_y)\\n    n = n_left + n_right\\n    return (n_left * mse(left_y) + n_right * mse(right_y)) / n\\n\\nthresholds = [1.5, 2.5, 3.5, 4.5, 5.5, 6.5, 7.5]\\nfor t in thresholds:\\n    left_y = [y[i] for i in range(len(x)) if x[i] <= t]\\n    right_y = [y[i] for i in range(len(x)) if x[i] > t]\\n    wmse = weighted_mse(left_y, right_y)\\n    gain = mse_root - wmse\\n    print(f\\"\\u041f\\u043e\\u0440\\u043e\\u0433 {t}: MSE = {wmse:.3f}, \\u043f\\u0440\\u0438\\u0440\\u043e\\u0441\\u0442 = {gain:.3f}\\")"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "\\u0420\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u044b \\u0432\\u044b\\u0447\\u0438\\u0441\\u043b\\u0435\\u043d\\u0438\\u0439:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "t=1.5: \\u043b\\u0435\\u0432\\u0430\\u044f \\u0447\\u0430\\u0441\\u0442\\u044c [2], MSE=0; \\u043f\\u0440\\u0430\\u0432\\u0430\\u044f [4,5,4,5,7,8,9], MSE\\u22482.81; \\u0432\\u0437\\u0432\\u0435\\u0448\\u0435\\u043d\\u043d\\u0430\\u044f = (1*0 + 7*2.81)/8 \\u2248 2.46; \\u043f\\u0440\\u0438\\u0440\\u043e\\u0441\\u0442 \\u2248 2.29"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "t=2.5: \\u043b\\u0435\\u0432\\u0430\\u044f [2,4], MSE=1; \\u043f\\u0440\\u0430\\u0432\\u0430\\u044f [5,4,5,7,8,9], MSE\\u22482.47; \\u0432\\u0437\\u0432\\u0435\\u0448\\u0435\\u043d\\u043d\\u0430\\u044f = (2*1 + 6*2.47)/8 \\u2248 2.10; \\u043f\\u0440\\u0438\\u0440\\u043e\\u0441\\u0442 \\u2248 2.65"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "t=3.5: \\u043b\\u0435\\u0432\\u0430\\u044f [2,4,5], MSE\\u22481.56; \\u043f\\u0440\\u0430\\u0432\\u0430\\u044f [4,5,7,8,9], MSE\\u22482.80; \\u0432\\u0437\\u0432\\u0435\\u0448\\u0435\\u043d\\u043d\\u0430\\u044f = (3*1.56 + 5*2.80)/8 \\u2248 2.34; \\u043f\\u0440\\u0438\\u0440\\u043e\\u0441\\u0442 \\u2248 2.41"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "t=4.5: \\u043b\\u0435\\u0432\\u0430\\u044f [2,4,5,4], MSE=1.25; \\u043f\\u0440\\u0430\\u0432\\u0430\\u044f [5,7,8,9], MSE\\u22482.19; \\u0432\\u0437\\u0432\\u0435\\u0448\\u0435\\u043d\\u043d\\u0430\\u044f = (4*1.25 + 4*2.19)/8 \\u2248 1.72; \\u043f\\u0440\\u0438\\u0440\\u043e\\u0441\\u0442 \\u2248 3.03"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "t=5.5: \\u043b\\u0435\\u0432\\u0430\\u044f [2,4,5,4,5], MSE=1.36; \\u043f\\u0440\\u0430\\u0432\\u0430\\u044f [7,8,9], MSE=0.67; \\u0432\\u0437\\u0432\\u0435\\u0448\\u0435\\u043d\\u043d\\u0430\\u044f = (5*1.36 + 3*0.67)/8 \\u2248 1.10; \\u043f\\u0440\\u0438\\u0440\\u043e\\u0441\\u0442 \\u2248 3.65"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "t=6.5: \\u043b\\u0435\\u0432\\u0430\\u044f [2,4,5,4,5,7], MSE=2.33; \\u043f\\u0440\\u0430\\u0432\\u0430\\u044f [8,9], MSE=0.25; \\u0432\\u0437\\u0432\\u0435\\u0448\\u0435\\u043d\\u043d\\u0430\\u044f = (6*2.33 + 2*0.25)/8 \\u2248 1.81; \\u043f\\u0440\\u0438\\u0440\\u043e\\u0441\\u0442 \\u2248 2.94"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "t=7.5: \\u043b\\u0435\\u0432\\u0430\\u044f [2,4,5,4,5,7,8], MSE=2.98; \\u043f\\u0440\\u0430\\u0432\\u0430\\u044f [9], MSE=0; \\u0432\\u0437\\u0432\\u0435\\u0448\\u0435\\u043d\\u043d\\u0430\\u044f = (7*2.98 + 1*0)/8 \\u2248 2.61; \\u043f\\u0440\\u0438\\u0440\\u043e\\u0441\\u0442 \\u2248 2.14"}]}]}]}, {"type": "calloutInfo", "content": [{"type": "text", "text": "\\u041d\\u0430\\u0438\\u0431\\u043e\\u043b\\u044c\\u0448\\u0438\\u0439 \\u043f\\u0440\\u0438\\u0440\\u043e\\u0441\\u0442 \\u0438\\u043d\\u0444\\u043e\\u0440\\u043c\\u0430\\u0446\\u0438\\u0438 \\u0434\\u043e\\u0441\\u0442\\u0438\\u0433\\u0430\\u0435\\u0442\\u0441\\u044f \\u043f\\u0440\\u0438 \\u043f\\u043e\\u0440\\u043e\\u0433\\u0435 t=5.5: \\u043f\\u0440\\u0438\\u0440\\u043e\\u0441\\u0442 \\u2248 3.65. \\u042d\\u0442\\u043e \\u043b\\u0443\\u0447\\u0448\\u0438\\u0439 \\u043f\\u0435\\u0440\\u0432\\u044b\\u0439 \\u043f\\u043e\\u0440\\u043e\\u0433 \\u0434\\u043b\\u044f \\u0440\\u0430\\u0437\\u0431\\u0438\\u0435\\u043d\\u0438\\u044f."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "\\u0428\\u0430\\u0433 3: \\u0421\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u0435 \\u0441 \\u0430\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u044b\\u043c\\u0438 \\u043f\\u043e\\u0440\\u043e\\u0433\\u0430\\u043c\\u0438"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "\\u041c\\u044b \\u0432\\u0438\\u0434\\u0438\\u043c, \\u0447\\u0442\\u043e \\u043f\\u043e\\u0440\\u043e\\u0433 5.5 \\u0434\\u0430\\u0451\\u0442 \\u043c\\u0430\\u043a\\u0441\\u0438\\u043c\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 \\u043f\\u0440\\u0438\\u0440\\u043e\\u0441\\u0442. \\u041f\\u043e\\u0440\\u043e\\u0433 4.5 \\u0442\\u0430\\u043a\\u0436\\u0435 \\u043d\\u0435\\u043f\\u043b\\u043e\\u0445 (\\u043f\\u0440\\u0438\\u0440\\u043e\\u0441\\u0442 3.03), \\u043d\\u043e \\u0443\\u0441\\u0442\\u0443\\u043f\\u0430\\u0435\\u0442. \\u041f\\u043e\\u0440\\u043e\\u0433\\u0438 1.5 \\u0438 7.5 \\u0434\\u0430\\u044e\\u0442 \\u043c\\u0435\\u043d\\u044c\\u0448\\u0438\\u0439 \\u043f\\u0440\\u0438\\u0440\\u043e\\u0441\\u0442. \\u042d\\u0442\\u043e \\u043b\\u043e\\u0433\\u0438\\u0447\\u043d\\u043e: \\u0434\\u0430\\u043d\\u043d\\u044b\\u0435 \\u0438\\u043c\\u0435\\u044e\\u0442 \\u0432\\u043e\\u0437\\u0440\\u0430\\u0441\\u0442\\u0430\\u044e\\u0449\\u0438\\u0439 \\u0442\\u0440\\u0435\\u043d\\u0434, \\u0438 \\u0440\\u0430\\u0437\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u0435 \\u0432 \\u0441\\u0435\\u0440\\u0435\\u0434\\u0438\\u043d\\u0435 (\\u043e\\u043a\\u043e\\u043b\\u043e 5.5) \\u043b\\u0443\\u0447\\u0448\\u0435 \\u0432\\u0441\\u0435\\u0433\\u043e \\u043e\\u0442\\u0434\\u0435\\u043b\\u044f\\u0435\\u0442 \\u043d\\u0438\\u0437\\u043a\\u0438\\u0435 \\u0437\\u043d\\u0430\\u0447\\u0435\\u043d\\u0438\\u044f \\u043e\\u0442 \\u0432\\u044b\\u0441\\u043e\\u043a\\u0438\\u0445."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "\\u041f\\u0440\\u043e\\u0432\\u0435\\u0440\\u043a\\u0430 \\u043d\\u0430 Python"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "\\u0423\\u0431\\u0435\\u0434\\u0438\\u043c\\u0441\\u044f \\u0432 \\u043f\\u0440\\u0430\\u0432\\u0438\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u0438 \\u0440\\u0430\\u0441\\u0447\\u0451\\u0442\\u043e\\u0432 \\u0441 \\u043f\\u043e\\u043c\\u043e\\u0449\\u044c\\u044e \\u043a\\u043e\\u0434\\u0430:"}]}, {"type": "codeBlock", "attrs": {"language": "python"}, "content": [{"type": "text", "text": "best_gain = -1\\nbest_t = None\\nfor t in thresholds:\\n    left_y = [y[i] for i in range(len(x)) if x[i] <= t]\\n    right_y = [y[i] for i in range(len(x)) if x[i] > t]\\n    wmse = weighted_mse(left_y, right_y)\\n    gain = mse_root - wmse\\n    if gain > best_gain:\\n        best_gain = gain\\n        best_t = t\\nprint(f\\"\\u041b\\u0443\\u0447\\u0448\\u0438\\u0439 \\u043f\\u043e\\u0440\\u043e\\u0433: {best_t}, \\u043f\\u0440\\u0438\\u0440\\u043e\\u0441\\u0442: {best_gain:.3f}\\")"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "\\u0412\\u044b\\u0432\\u043e\\u0434: \\u041b\\u0443\\u0447\\u0448\\u0438\\u0439 \\u043f\\u043e\\u0440\\u043e\\u0433: 5.5, \\u043f\\u0440\\u0438\\u0440\\u043e\\u0441\\u0442: 3.65"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "\\u0417\\u0430\\u043a\\u0440\\u0435\\u043f\\u043b\\u0435\\u043d\\u0438\\u0435 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0438\\u0430\\u043b\\u0430"}]}, {"type": "flipcardGrid", "attrs": {"columns": 2}, "content": [{"type": "flipcard", "attrs": {"question": "\\u0427\\u0442\\u043e \\u0442\\u0430\\u043a\\u043e\\u0435 MSE \\u0432 \\u043a\\u043e\\u043d\\u0442\\u0435\\u043a\\u0441\\u0442\\u0435 \\u0434\\u0435\\u0440\\u0435\\u0432\\u0430 \\u0440\\u0435\\u0433\\