e=42)\\nclf_limited.fit(X_train, y_train)\\ntrain_acc_lim = accuracy_score(y_train, clf_limited.predict(X_train))\\ntest_acc_lim = accuracy_score(y_test, clf_limited.predict(X_test))\\nprint(f\\"\\u0421 \\u043e\\u0433\\u0440\\u0430\\u043d\\u0438\\u0447\\u0435\\u043d\\u0438\\u0435\\u043c: train={train_acc_lim:.3f}, test={test_acc_lim:.3f}\\")"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "\\u041e\\u0431\\u044b\\u0447\\u043d\\u043e \\u0433\\u043b\\u0443\\u0431\\u043e\\u043a\\u043e\\u0435 \\u0434\\u0435\\u0440\\u0435\\u0432\\u043e \\u043f\\u043e\\u043a\\u0430\\u0437\\u044b\\u0432\\u0430\\u0435\\u0442 accuracy \\u043d\\u0430 \\u0442\\u0440\\u0435\\u043d\\u0438\\u0440\\u043e\\u0432\\u043e\\u0447\\u043d\\u043e\\u0439 \\u0432\\u044b\\u0431\\u043e\\u0440\\u043a\\u0435 \\u043e\\u043a\\u043e\\u043b\\u043e 1.0, \\u0430 \\u043d\\u0430 \\u0442\\u0435\\u0441\\u0442\\u043e\\u0432\\u043e\\u0439 \\u2014 \\u0437\\u0430\\u043c\\u0435\\u0442\\u043d\\u043e \\u043d\\u0438\\u0436\\u0435. \\u041e\\u0433\\u0440\\u0430\\u043d\\u0438\\u0447\\u0435\\u043d\\u043d\\u043e\\u0435 \\u0434\\u0435\\u0440\\u0435\\u0432\\u043e \\u043c\\u043e\\u0436\\u0435\\u0442 \\u043d\\u0435\\u043c\\u043d\\u043e\\u0433\\u043e \\u0443\\u0441\\u0442\\u0443\\u043f\\u0430\\u0442\\u044c \\u043d\\u0430 \\u0442\\u0440\\u0435\\u043d\\u0438\\u0440\\u043e\\u0432\\u043a\\u0435, \\u043d\\u043e \\u043f\\u0440\\u0435\\u0432\\u043e\\u0441\\u0445\\u043e\\u0434\\u0438\\u0442\\u044c \\u043d\\u0430 \\u0442\\u0435\\u0441\\u0442\\u0435. \\u042d\\u0442\\u043e \\u043d\\u0430\\u0433\\u043b\\u044f\\u0434\\u043d\\u043e \\u0434\\u0435\\u043c\\u043e\\u043d\\u0441\\u0442\\u0440\\u0438\\u0440\\u0443\\u0435\\u0442 \\u043f\\u0440\\u043e\\u0431\\u043b\\u0435\\u043c\\u0443 \\u043f\\u0435\\u0440\\u0435\\u043e\\u0431\\u0443\\u0447\\u0435\\u043d\\u0438\\u044f."}]}, {"type": "calloutWarning", "content": [{"type": "text", "text": "\\u041d\\u0435 \\u0437\\u0430\\u0431\\u044b\\u0432\\u0430\\u0439\\u0442\\u0435: \\u0438\\u0434\\u0435\\u0430